input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?s ?tsid ?p WHERE {
  ?s a brick:Zone ; brick:hasName "Basement".
  ?point brick:hasLocation ?s ; a brick:Air_Temperature.
  ?point ref:hasTimeseriesId ?tsid .
}

SELECT ?s ?type WHERE {
  ?s a brick:Zone .
  ?s a ?type .
  FILTER(str(?s) LIKE "%asement%" || str(?s) LIKE "%ase%")
}

SELECT ?s ?label WHERE {
  ?s a brick:Zone .
  ?s brick:hasName ?label .
} LIMIT 100

SELECT ?s ?label WHERE {
  ?s brick:hasName ?label .
  FILTER(str(?label) LIKE "%asement%")
} LIMIT 50

SELECT ?s ?label WHERE {
  ?s brick:hasName ?label .
  FILTER(str(?label) LIKE "%asement%")
} LIMIT 50

